package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SessionSsoTtlSecondsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property session sso ttl seconds of tenant config ")
  void test_session_sso_ttl_seconds_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> SessionSsoTtlSecondsVO.tryFrom(null));
    Assertions.assertEquals(1, SessionSsoTtlSecondsVO.from(1).getSessionSsoTtlSeconds());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> SessionSsoTtlSecondsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", SessionSsoTtlSecondsVO.from(1).toString());
  }
}
